import os

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException
from pydantic import AwareDatetime, BaseModel, Field

from pulso import correo, db, reloj

router = APIRouter()


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
    if not x_admin_key or x_admin_key != os.environ.get('PULSO_ADMIN_KEY'):
        raise HTTPException(401, 'Clave de administración inválida')


def ver_clase(clase):
    return dict(clase, lugares_libres=clase['cupo'] - db.confirmadas(clase['id']))


def ver_reserva(reserva):
    return {k: reserva[k] for k in ('id', 'clase_id', 'estado', 'creada')}


@router.get('/clases')
def listar_clases():
    ahora = reloj.ahora()
    return [ver_clase(c) for c in db.clases() if db.a_fecha(c['inicio']) > ahora]


@router.get('/clases/{clase_id}')
def obtener_clase(clase_id: int):
    clase = db.clase(clase_id)
    if clase is None:
        raise HTTPException(404, 'No existe la clase')
    return ver_clase(clase)


class NuevaClase(BaseModel):
    nombre: str = Field(min_length=1)
    instructor: str = Field(min_length=1)
    inicio: AwareDatetime
    duracion_min: int = Field(gt=0)
    cupo: int = Field(gt=0)


@router.post('/admin/clases', status_code=201, dependencies=[Depends(admin)])
def crear_clase(datos: NuevaClase):
    return ver_clase(db.crear_clase(**datos.model_dump()))


class NuevaReserva(BaseModel):
    clase_id: int


@router.post('/reservas', status_code=201)
def reservar(datos: NuevaReserva, socio=Depends(socio_actual)):
    with db.transaccion() as con:
        clase = db.q_una(con, 'SELECT * FROM clases WHERE id = ?', (datos.clase_id,))
        if clase is None:
            raise HTTPException(404, 'No existe la clase')
        socio = db.q_una(con, 'SELECT * FROM socios WHERE id = ?', (socio['id'],))
        inicio = db.a_fecha(clase['inicio'])
        if inicio <= reloj.ahora():
            raise HTTPException(409, 'La clase ya empezó')
        if db.q_tiene_confirmada(con, socio['id'], clase['id']):
            raise HTTPException(409, 'Ya tenés una reserva para esta clase')
        if db.q_confirmadas(con, clase['id']) >= clase['cupo']:
            raise HTTPException(409, 'La clase no tiene lugar')
        if socio['creditos'] < 1:
            raise HTTPException(409, 'No te quedan créditos')
        reserva = db.q_crear_reserva(con, socio['id'], clase['id'], reloj.ahora())
        con.execute('UPDATE socios SET creditos = creditos - 1 WHERE id = ?', (socio['id'],))
        db.q_correo(con, socio['email'],
                    f"Reserva confirmada: {clase['nombre']} el {correo.fecha_y_hora(inicio)}",
                    f"Hola {socio['nombre']}, te esperamos en {clase['nombre']} con {clase['instructor']}.",
                    reloj.ahora())
    return ver_reserva(reserva)


def posicion_json(clase_id, posicion):
    return {'clase_id': clase_id, 'posicion': posicion}


@router.post('/clases/{clase_id}/espera', status_code=201)
def anotarse_en_espera(clase_id: int, socio=Depends(socio_actual)):
    with db.transaccion() as con:
        clase = db.q_una(con, 'SELECT * FROM clases WHERE id = ?', (clase_id,))
        if clase is None:
            raise HTTPException(404, 'No existe la clase')
        socio = db.q_una(con, 'SELECT * FROM socios WHERE id = ?', (socio['id'],))
        if db.q_confirmadas(con, clase_id) < clase['cupo']:
            raise HTTPException(409, 'La clase tiene lugar: reservá directo')
        if db.q_tiene_confirmada(con, socio['id'], clase_id):
            raise HTTPException(409, 'Ya tenés una reserva para esta clase')
        if db.q_posicion(con, socio['id'], clase_id) is not None:
            raise HTTPException(409, 'Ya estás en la lista de espera')
        if db.a_fecha(clase['inicio']) <= reloj.ahora():
            raise HTTPException(409, 'La clase ya empezó')
        if socio['creditos'] < 1:
            raise HTTPException(409, 'No te quedan créditos')
        con.execute('INSERT INTO espera (socio_id, clase_id) VALUES (?, ?)', (socio['id'], clase_id))
        return posicion_json(clase_id, db.q_posicion(con, socio['id'], clase_id))


@router.get('/clases/{clase_id}/espera')
def ver_espera(clase_id: int, socio=Depends(socio_actual)):
    with db.transaccion() as con:
        if db.q_una(con, 'SELECT id FROM clases WHERE id = ?', (clase_id,)) is None:
            raise HTTPException(404, 'No existe la clase')
        posicion = db.q_posicion(con, socio['id'], clase_id)
        if posicion is None:
            raise HTTPException(404, 'No estás en la lista de espera')
        return posicion_json(clase_id, posicion)


@router.delete('/clases/{clase_id}/espera', status_code=204)
def bajarse_de_espera(clase_id: int, socio=Depends(socio_actual)):
    with db.transaccion() as con:
        if db.q_una(con, 'SELECT id FROM clases WHERE id = ?', (clase_id,)) is None:
            raise HTTPException(404, 'No existe la clase')
        if db.q_posicion(con, socio['id'], clase_id) is None:
            raise HTTPException(404, 'No estás en la lista de espera')
        con.execute('DELETE FROM espera WHERE socio_id = ? AND clase_id = ?', (socio['id'], clase_id))


def asignar_lugares(con, clase):
    """Pasa los lugares libres al principio de la lista de espera. Va dentro de la transacción del llamador."""
    inicio = db.a_fecha(clase['inicio'])
    ahora = reloj.ahora()
    if inicio <= ahora:
        return
    cuando = correo.fecha_y_hora(inicio)
    while db.q_confirmadas(con, clase['id']) < clase['cupo']:
        primero = db.q_una(con, 'SELECT * FROM espera WHERE clase_id = ? ORDER BY id LIMIT 1', (clase['id'],))
        if primero is None:
            return
        con.execute('DELETE FROM espera WHERE id = ?', (primero['id'],))
        socio = db.q_una(con, 'SELECT * FROM socios WHERE id = ?', (primero['socio_id'],))
        if db.q_tiene_confirmada(con, socio['id'], clase['id']):
            continue
        if socio['creditos'] < 1:
            db.q_correo(con, socio['email'], f"No pudimos darte el lugar: {clase['nombre']} el {cuando}",
                        f"Hola {socio['nombre']}, se liberó un lugar pero no te quedan créditos.", ahora)
            continue
        db.q_crear_reserva(con, socio['id'], clase['id'], ahora)
        con.execute('UPDATE socios SET creditos = creditos - 1 WHERE id = ?', (socio['id'],))
        db.q_correo(con, socio['email'], f"Se liberó un lugar: {clase['nombre']} el {cuando}",
                    f"Hola {socio['nombre']}, tenés lugar en {clase['nombre']} con {clase['instructor']}.", ahora)


@router.post('/admin/reservas/{reserva_id}/cancelar', dependencies=[Depends(admin)])
def cancelar_reserva(reserva_id: int):
    with db.transaccion() as con:
        reserva = db.q_una(con, 'SELECT * FROM reservas WHERE id = ?', (reserva_id,))
        if reserva is None:
            raise HTTPException(404, 'No existe la reserva')
        if reserva['estado'] == 'cancelada':
            raise HTTPException(409, 'La reserva ya estaba cancelada')
        con.execute("UPDATE reservas SET estado = 'cancelada' WHERE id = ?", (reserva_id,))
        con.execute('UPDATE socios SET creditos = creditos + 1 WHERE id = ?', (reserva['socio_id'],))
        clase = db.q_una(con, 'SELECT * FROM clases WHERE id = ?', (reserva['clase_id'],))
        if reserva['estado'] == 'confirmada':
            asignar_lugares(con, clase)
        return ver_reserva(db.q_una(con, 'SELECT * FROM reservas WHERE id = ?', (reserva_id,)))


class CambioClase(BaseModel):
    cupo: StrictInt = Field(gt=0)


@router.patch('/admin/clases/{clase_id}', dependencies=[Depends(admin)])
def cambiar_clase(clase_id: int, datos: CambioClase):
    with db.transaccion() as con:
        clase = db.q_una(con, 'SELECT * FROM clases WHERE id = ?', (clase_id,))
        if clase is None:
            raise HTTPException(404, 'No existe la clase')
        if datos.cupo < db.q_confirmadas(con, clase_id):
            raise HTTPException(409, 'El cupo no puede ser menor a las reservas confirmadas')
        con.execute('UPDATE clases SET cupo = ? WHERE id = ?', (datos.cupo, clase_id))
        clase['cupo'] = datos.cupo
        asignar_lugares(con, clase)
        return dict(clase, lugares_libres=clase['cupo'] - db.q_confirmadas(con, clase_id))


@router.get('/reservas')
def mis_reservas(socio=Depends(socio_actual)):
    return [ver_reserva(r) for r in db.reservas_de(socio['id'])]


